import { onMounted, onUnmounted, watch, type Ref } from "vue";
import { resolveElement, useFloatingLayer } from "../lib/composables";

type HitTest = (target: Element) => boolean;
const openScopes = new Set<HitTest>();

export function useBlockDismiss(
  open: Ref<boolean>,
  root: Ref<unknown>,
  close: () => void,
  consume = false,
) {
  const layer = useFloatingLayer(open, root);
  const pendingClicks = new Set<() => void>();
  let stopWatching: (() => void) | undefined;
  function interceptActivation(source: Event) {
    const release = () => {
      window.removeEventListener("click", click, true);
      window.removeEventListener("pointerdown", replacement, true);
      window.removeEventListener("pointercancel", replacement, true);
      window.removeEventListener("keydown", release, true);
      pendingClicks.delete(release);
    };
    function click(event: MouseEvent) {
      event.preventDefault();
      event.stopPropagation();
      release();
    }
    function replacement(event: Event) {
      if (event !== source) release();
    }
    pendingClicks.add(release);
    window.addEventListener("click", click, true);
    window.addEventListener("pointerdown", replacement, true);
    window.addEventListener("pointercancel", replacement, true);
    window.addEventListener("keydown", release, true);
  }
  onMounted(() => {
    stopWatching = watch(
      open,
      (visible, _, cleanup) => {
        if (!visible) return;
        const contains: HitTest = (target) =>
          resolveElement<HTMLElement>(root.value)?.contains(target) ?? false;
        const keydown = (event: KeyboardEvent) => {
          if (layer.claimEscape(event)) close();
        };
        const pointerdown = (event: PointerEvent) => {
          const target = event.target;
          if (
            !(target instanceof Element) ||
            contains(target) ||
            layer.containsHigher(target)
          )
            return;
          let anotherScope = false;
          if (consume)
            for (const hit of openScopes)
              if (hit !== contains && hit(target)) {
                anotherScope = true;
                break;
              }
          if (consume && !anotherScope) interceptActivation(event);
          close();
        };
        openScopes.add(contains);
        window.addEventListener("keydown", keydown);
        window.addEventListener("pointerdown", pointerdown, true);
        cleanup(() => {
          openScopes.delete(contains);
          window.removeEventListener("keydown", keydown);
          window.removeEventListener("pointerdown", pointerdown, true);
        });
      },
      { immediate: true },
    );
  });
  onUnmounted(() => {
    stopWatching?.();
    for (const release of pendingClicks) release();
  });
  return layer;
}

export { default as MorphingSearch } from "./src/MorphingSearch.vue";
export { default as MorphingSearchChips } from "./src/MorphingSearchChips.vue";
export type { MorphingSearchItem } from "./src/MorphingSearch.vue";

export type * from "./src/api-types";

// Vue public prop types, derived from the actual components.
export type MorphingSearchChipsProps = InstanceType<
  (typeof import("./MorphingSearchChips.vue"))["default"]
>["$props"];
export type MorphingSearchProps = InstanceType<
  (typeof import("./MorphingSearch.vue"))["default"]
>["$props"];

import {
  computed,
  nextTick,
  onMounted,
  onUnmounted,
  onUpdated,
  ref,
  useId,
  watch,
} from "vue";
import { resolveElement, useReducedMotion } from "../../../lib/composables";
import { useControllable, type Content } from "../../shared";
import { useBlockDismiss } from "../../dismiss";
import { useSearchCursor } from "../../search-cursor";
export interface SearchChipsOptions {
  chips?: string[];
  defaultChips: string[];
  query?: string;
  defaultQuery: string;
  recents?: string[];
  defaultRecents: string[];
  storageKey?: string;
  maxRecents: number;
  suggestions: string[];
  filter?: ((term: string, query: string) => boolean) | false;
  maxSuggestions: number;
  loading?: boolean;
  maxChips?: number;
  normalize?: (term: string) => string | null;
  emptyState?: Content;
  side: "top" | "bottom" | "auto";
  open?: boolean;
  defaultOpen: boolean;
  disabled?: boolean;
}
interface Row {
  id: string;
  label: string;
  kind: "query" | "recent" | "suggestion";
}
interface Events {
  chips(value: string[]): void;
  query(value: string): void;
  recents(value: string[]): void;
  open(value: boolean): void;
}
const canonical = (value: string) => value.trim().toLowerCase();
const includes = (term: string, query: string) =>
  term.toLowerCase().includes(query.toLowerCase());
export function useSearchChips(props: SearchChipsOptions, events: Events) {
  const chips = useControllable(
    () => props.chips,
    props.defaultChips,
    events.chips,
  );
  const query = useControllable(
    () => props.query,
    props.defaultQuery,
    events.query,
  );
  const openState = useControllable(
    () => props.open,
    props.defaultOpen,
    events.open,
  );
  const localRecents = ref(props.defaultRecents);
  const recents = computed(() => props.recents ?? localRecents.value);
  const open = computed(() => openState.value && !props.disabled);
  const trimmed = computed(() => query.value.trim());
  const marked = ref<string | null>(null);
  const rtl = ref(false);
  const placed = ref<"top" | "bottom">(
    props.side === "bottom" ? "bottom" : "top",
  );
  const root = ref<HTMLElement>();
  const field = ref<unknown>();
  const chipsRow = ref<HTMLElement>();
  const panel = ref<unknown>();
  const rowContainer = ref<HTMLElement>();
  const panelSize = ref({ width: 0, height: 0 });
  const panelFloor = ref(0);
  const announcement = ref({ text: "", count: 0 });
  const reduce = useReducedMotion();
  const id = useId();
  let mounted = false,
    disposed = false;
  const rows = computed<Row[]>(() => {
    const term = trimmed.value;
    if (!term)
      return recents.value.map((label) => ({
        id: `recent:${label}`,
        label,
        kind: "recent",
      }));
    const excluded = new Set([
      term.toLowerCase(),
      ...chips.value.map((value) => value.toLowerCase()),
    ]);
    const matches: Row[] = [];
    const pools = [
      { kind: "recent" as const, terms: recents.value, test: includes },
      {
        kind: "suggestion" as const,
        terms: props.suggestions,
        test: props.filter === false ? () => true : (props.filter ?? includes),
      },
    ];
    for (const pool of pools)
      for (const label of pool.terms) {
        const key = label.toLowerCase();
        if (excluded.has(key) || !pool.test(label, term)) continue;
        excluded.add(key);
        matches.push({ id: `${pool.kind}:${label}`, label, kind: pool.kind });
      }
    return [
      { id: `query:${term}`, label: term, kind: "query" },
      ...matches.slice(0, props.maxSuggestions),
    ];
  });
  const cursor = useSearchCursor(rows, trimmed);
  const active = computed(() => rows.value[cursor.active.value]);
  const panelOpen = computed(
    () =>
      open.value &&
      (!!rows.value.length ||
        !!props.loading ||
        (!trimmed.value && props.emptyState != null)),
  );
  const below = computed(() => placed.value === "bottom");
  const layer = useBlockDismiss(open, root, () => {
    openState.value = false;
  });
  const input = () => resolveElement<HTMLInputElement>(field.value);
  function announce(text: string) {
    announcement.value = { text, count: announcement.value.count + 1 };
  }
  function setRecents(value: string[]) {
    if (props.recents === undefined) localRecents.value = value;
    events.recents(value);
    if (props.storageKey && props.recents === undefined)
      try {
        localStorage.setItem(props.storageKey, JSON.stringify(value));
      } catch {}
  }
  function restore() {
    if (!mounted || !props.storageKey || props.recents !== undefined) return;
    try {
      const saved: unknown = JSON.parse(
        localStorage.getItem(props.storageKey) ?? "null",
      );
      if (Array.isArray(saved))
        localRecents.value = saved
          .filter((item): item is string => typeof item === "string")
          .slice(0, props.maxRecents);
    } catch {}
  }
  function add(term: string) {
    if (props.disabled) return;
    const value = props.normalize ? props.normalize(term) : term.trim();
    if (!value) return;
    const exists = chips.value.some(
      (chip) => canonical(chip) === canonical(value),
    );
    if (
      !exists &&
      props.maxChips !== undefined &&
      chips.value.length >= props.maxChips
    ) {
      announce(`Up to ${props.maxChips} filters`);
      return;
    }
    if (!exists) {
      chips.value = [...chips.value, value];
      announce(`Added filter ${value}`);
    }
    setRecents(
      [
        value,
        ...recents.value.filter(
          (recent) => canonical(recent) !== canonical(value),
        ),
      ].slice(0, props.maxRecents),
    );
    query.value = "";
  }
  function remove(term: string) {
    chips.value = chips.value.filter((chip) => chip !== term);
    announce(`Removed filter ${term}`);
    input()?.focus();
  }
  function removeRecent(term: string) {
    setRecents(recents.value.filter((recent) => recent !== term));
    announce(`Removed ${term} from recent searches`);
  }
  function stepMark(delta: number) {
    const at =
      marked.value === null
        ? chips.value.length
        : chips.value.indexOf(marked.value);
    const next = at + delta;
    marked.value =
      next >= chips.value.length || !chips.value.length
        ? null
        : chips.value[Math.max(0, next)]!;
  }
  function key(event: KeyboardEvent) {
    if (event.isComposing || event.keyCode === 229) return;
    const field = event.currentTarget as HTMLInputElement;
    const atStart = field.selectionStart === 0 && field.selectionEnd === 0;
    const backward = rtl.value ? "ArrowRight" : "ArrowLeft";
    const forward = rtl.value ? "ArrowLeft" : "ArrowRight";
    if (marked.value !== null) {
      if (event.key === "Backspace" || event.key === "Delete") {
        event.preventDefault();
        const term = marked.value;
        marked.value = null;
        remove(term);
        return;
      }
      if (event.key === backward || event.key === forward) {
        event.preventDefault();
        stepMark(event.key === backward ? -1 : 1);
        return;
      }
      marked.value = null;
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        return;
      }
    }
    if (event.key === "Escape" && query.value !== "") {
      event.preventDefault();
      event.stopPropagation();
      query.value = "";
      return;
    }
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (open.value) cursor.moveActive(event.key === "ArrowDown" ? 1 : -1);
      else openState.value = true;
      return;
    }
    if (event.key === "Enter" && panelOpen.value && active.value) {
      event.preventDefault();
      add(active.value.label);
      return;
    }
    if (
      event.key === "Delete" &&
      panelOpen.value &&
      active.value?.kind === "recent"
    ) {
      event.preventDefault();
      removeRecent(active.value.label);
      return;
    }
    if (atStart && chips.value.length) {
      if (event.key === "Backspace") {
        event.preventDefault();
        marked.value = chips.value.at(-1)!;
        announce(
          `${marked.value} selected. Press Backspace again to remove it.`,
        );
      } else if (event.key === backward) {
        event.preventDefault();
        stepMark(-1);
      }
    }
  }
  function focus(event: PointerEvent) {
    if (props.disabled || (event.target as Element).closest("button,input,a"))
      return;
    event.preventDefault();
    input()?.focus();
    openState.value = true;
  }
  function blur(event: FocusEvent) {
    if (
      root.value?.contains(event.relatedTarget as Node) ||
      layer.containsHigher(event.relatedTarget)
    )
      return;
    marked.value = null;
    openState.value = false;
  }
  let observers: ResizeObserver[] = [];
  function disconnect() {
    for (const observer of observers) observer.disconnect();
    observers = [];
  }
  function observe() {
    disconnect();
    const node = resolveElement<HTMLElement>(panel.value),
      row = rowContainer.value;
    if (disposed || !panelOpen.value || !node || !row) return;
    const measurePanel = () => {
      const width = node.offsetWidth,
        height = node.offsetHeight;
      if (width !== panelSize.value.width || height !== panelSize.value.height)
        panelSize.value = { width, height };
    };
    const measureRows = () => {
      panelFloor.value = Math.max(panelFloor.value, row.offsetHeight + 16);
    };
    measureRows();
    measurePanel();
    if (typeof ResizeObserver !== "undefined") {
      for (const [element, measure] of [
        [node, measurePanel],
        [row, measureRows],
      ] as const) {
        const observer = new ResizeObserver(measure);
        observer.observe(element);
        observers.push(observer);
      }
    }
  }
  watch(
    [() => props.storageKey, () => props.recents, () => props.maxRecents],
    restore,
  );
  watch(open, (value) => {
    if (value) cursor.moveTo(null);
  });
  watch(panelOpen, (value) => {
    if (value) {
      panelFloor.value = 0;
      if (props.side !== "auto") placed.value = props.side;
      else {
        const box = root.value?.getBoundingClientRect();
        if (box) {
          const after = innerHeight - box.bottom;
          placed.value = box.top < 320 && after > box.top ? "bottom" : "top";
        }
      }
    }
    void nextTick(observe);
  });
  watch(
    () => props.side,
    (value) => {
      if (value !== "auto") placed.value = value;
    },
  );
  watch(
    [cursor.active, panelOpen, rows],
    () =>
      void nextTick(() => {
        if (!disposed && panelOpen.value && rows.value.length)
          document
            .getElementById(`${id}-option-${cursor.active.value}`)
            ?.scrollIntoView({ block: "nearest" });
      }),
  );
  watch(chips, (value, before) => {
    if (marked.value && !value.includes(marked.value)) marked.value = null;
    if (value.length > before.length)
      void nextTick(() => {
        const row = chipsRow.value;
        if (!disposed && row && row.scrollWidth > row.clientWidth)
          row.scrollTo({
            left: (rtl.value ? -1 : 1) * row.scrollWidth,
            behavior: reduce.value ? "auto" : "smooth",
          });
      });
  });
  onMounted(() => {
    mounted = true;
    rtl.value =
      !!root.value && getComputedStyle(root.value).direction === "rtl";
    restore();
    observe();
  });
  onUpdated(observe);
  onUnmounted(() => {
    disposed = true;
    disconnect();
  });
  return {
    chips,
    query,
    recents,
    openState,
    open,
    marked,
    rtl,
    announcement,
    root,
    field,
    chipsRow,
    panel,
    rowContainer,
    panelSize,
    panelFloor,
    id,
    trimmed,
    reduce,
    rows,
    cursor,
    panelOpen,
    below,
    input,
    announce,
    setRecents,
    add,
    remove,
    removeRecent,
    key,
    focus,
    blur,
  };
}

import {
  computed,
  nextTick,
  onMounted,
  onUnmounted,
  ref,
  useId,
  watch,
} from "vue";
import { resolveElement, useReducedMotion } from "../../../lib/composables";
import { EASE_OUT } from "../../../lib/ease";
import { useControllable, useDialog, type Content } from "../../shared";
import { useSearchCursor } from "../../search-cursor";
export interface SearchOverlayItem {
  id: string;
  title: string;
  description?: string;
  keywords?: string[];
  icon?: Content;
  onSelect?: () => void;
}
interface Options {
  items: SearchOverlayItem[];
  open?: boolean;
  defaultOpen: boolean;
  shortcut: string;
}
type Events = {
  open(value: boolean): void;
  query(value: string): void;
  select(value: SearchOverlayItem): void;
};
export function useSearchOverlay(props: Options, events: Events) {
  const open = useControllable(
    () => props.open,
    props.defaultOpen,
    events.open,
  );
  const reduce = useReducedMotion();
  const query = ref("");
  const present = ref(open.value);
  const ready = ref(false);
  const anchor = ref<HTMLDivElement>();
  const trigger = ref<unknown>();
  const root = ref<HTMLElement>();
  const input = ref<HTMLInputElement>();
  const list = ref<unknown>();
  const id = useId();
  const box = ref({ top: 16, left: 16, width: 288 });
  const viewport = ref({ width: 0, height: 0 });
  const filtered = computed(() => {
    const term = query.value.trim().toLowerCase();
    if (!term) return props.items;
    return props.items.filter((item) =>
      `${item.title} ${item.description ?? ""} ${(item.keywords ?? []).join(" ")}`
        .toLowerCase()
        .includes(term),
    );
  });
  const cursor = useSearchCursor(filtered, query);
  const panelWidth = computed(() =>
    ready.value
      ? Math.max(
          box.value.width,
          Math.min(448, viewport.value.width - box.value.left - 16),
        )
      : box.value.width,
  );
  const resultsHeight = computed(() =>
    ready.value
      ? Math.max(96, Math.min(288, viewport.value.height - box.value.top - 80))
      : 288,
  );
  const collapsedClip = computed(
    () =>
      `inset(0px ${Math.max(0, panelWidth.value - box.value.width)}px ${resultsHeight.value}px 0px round 12px)`,
  );
  const shellStyle = computed(() => ({
    top: `${box.value.top}px`,
    left: `${box.value.left}px`,
    width: `${panelWidth.value}px`,
  }));
  const morph = computed(() =>
    reduce.value
      ? { duration: 0 }
      : { type: "spring" as const, duration: 0.58, bounce: 0.22 },
  );
  const clipTransition = computed(() =>
    reduce.value
      ? { duration: 0 }
      : {
          clipPath: { duration: 0.32, ease: EASE_OUT },
          opacity: { type: "spring" as const, duration: 0.58, bounce: 0.22 },
        },
  );
  let focusBefore: HTMLElement | null = null;
  let disposed = false;
  function measure() {
    if (typeof window === "undefined") return;
    const measured = anchor.value?.getBoundingClientRect();
    if (measured?.width)
      box.value = {
        top: measured.top,
        left: measured.left,
        width: measured.width,
      };
    viewport.value = { width: window.innerWidth, height: window.innerHeight };
  }
  function openSearch() {
    measure();
    focusBefore =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
    present.value = true;
    open.value = true;
  }
  function close() {
    if (query.value === "") events.query("");
    query.value = "";
    open.value = false;
  }
  function select(item: SearchOverlayItem) {
    item.onSelect?.();
    events.select(item);
    close();
  }
  function key(event: KeyboardEvent) {
    const direction =
      event.key === "ArrowDown" ? 1 : event.key === "ArrowUp" ? -1 : 0;
    if (direction) {
      event.preventDefault();
      cursor.moveActive(direction as 1 | -1);
    } else if (event.key === "Enter") {
      event.preventDefault();
      const item = filtered.value[cursor.active.value];
      if (item) select(item);
    }
  }
  function shortcut(event: KeyboardEvent) {
    if (event.key === "Escape" && open.value) {
      event.preventDefault();
      close();
      return;
    }
    const el = event.target instanceof HTMLElement ? event.target : null;
    if (
      open.value ||
      !props.shortcut ||
      event.repeat ||
      event.metaKey ||
      event.ctrlKey ||
      event.altKey ||
      event.shiftKey ||
      el?.isContentEditable ||
      el?.matches("input,textarea,select")
    )
      return;
    if (event.key.toLowerCase() === props.shortcut.toLowerCase()) {
      event.preventDefault();
      openSearch();
    }
  }
  function blockScroll(event: WheelEvent | TouchEvent) {
    if (!present.value) return;
    if (
      event.target instanceof Node &&
      resolveElement<HTMLElement>(list.value)?.contains(event.target)
    )
      return;
    event.preventDefault();
  }
  watch(query, events.query);
  watch(open, (value) => {
    if (value) {
      measure();
      present.value = true;
      query.value = "";
      cursor.moveTo(null);
      events.query("");
    } else
      void nextTick(() => {
        if (disposed) return;
        (focusBefore?.isConnected
          ? focusBefore
          : resolveElement<HTMLElement>(trigger.value)
        )?.focus();
      });
  });
  watch([cursor.active, open], () => {
    if (open.value)
      void nextTick(() => {
        if (!disposed)
          resolveElement<HTMLElement>(list.value)
            ?.querySelector<HTMLElement>(
              `[data-index="${cursor.active.value}"]`,
            )
            ?.scrollIntoView({ block: "nearest" });
      });
  });
  useDialog(open, root, () => input.value);
  let observer: ResizeObserver | undefined;
  onMounted(() => {
    ready.value = true;
    measure();
    if (anchor.value && typeof ResizeObserver !== "undefined") {
      observer = new ResizeObserver(measure);
      observer.observe(anchor.value);
    }
    window.addEventListener("resize", measure);
    document.addEventListener("scroll", measure, true);
    window.visualViewport?.addEventListener("resize", measure);
    window.visualViewport?.addEventListener("scroll", measure);
    window.addEventListener("keydown", shortcut);
    document.addEventListener("wheel", blockScroll, { passive: false });
    document.addEventListener("touchmove", blockScroll, { passive: false });
  });
  onUnmounted(() => {
    disposed = true;
    observer?.disconnect();
    window.removeEventListener("resize", measure);
    document.removeEventListener("scroll", measure, true);
    window.visualViewport?.removeEventListener("resize", measure);
    window.visualViewport?.removeEventListener("scroll", measure);
    window.removeEventListener("keydown", shortcut);
    document.removeEventListener("wheel", blockScroll);
    document.removeEventListener("touchmove", blockScroll);
  });
  return {
    open,
    reduce,
    query,
    present,
    anchor,
    trigger,
    root,
    input,
    list,
    id,
    shellId: `${id}-shell`,
    filtered,
    ...cursor,
    panelWidth,
    resultsHeight,
    collapsedClip,
    morph,
    clipTransition,
    shellStyle,
    openSearch,
    close,
    select,
    key,
  };
}

import { computed, shallowRef, watch, type Ref } from "vue";

export function useSearchCursor<T extends { id: string }>(
  rows: Ref<T[]>,
  query: Ref<string>,
) {
  const selected = shallowRef<{ id: string; query: string } | null>(null);
  const positions = computed(() => {
    const indices = new Map<string, number>();
    rows.value.forEach((row, index) => {
      if (!indices.has(row.id)) indices.set(row.id, index);
    });
    return indices;
  });
  const active = computed(() => {
    const selection = selected.value;
    if (!selection || selection.query !== query.value) return 0;
    return positions.value.get(selection.id) ?? 0;
  });
  watch(
    [positions, query],
    () => {
      const selection = selected.value;
      if (
        selection &&
        (selection.query !== query.value || !positions.value.has(selection.id))
      )
        selected.value = null;
    },
    { flush: "sync" },
  );
  function moveTo(id: string | null) {
    selected.value = id === null ? null : { id, query: query.value };
  }
  function moveActive(direction: 1 | -1) {
    const values = rows.value;
    if (!values.length) return;
    const next = Math.max(
      0,
      Math.min(values.length - 1, active.value + direction),
    );
    moveTo(values[next].id);
  }
  return { active, moveTo, moveActive };
}

import { useBlockDismiss } from "./dismiss";
import { resolveElement, useOverlay } from "../lib/composables";
import {
  computed,
  defineComponent,
  h,
  isVNode,
  onMounted,
  onUnmounted,
  ref,
  type Component,
  type Ref,
  type VNodeChild,
} from "vue";

export type Content = VNodeChild | Component;
export const RenderNode = defineComponent({
  props: ["node"],
  setup(props) {
    return () => {
      const node = props.node;
