  switch (event.key) {
    case "ArrowRight":
    case "ArrowDown":
      destination = (current + 1) % items.length;
      break;
    case "ArrowLeft":
    case "ArrowUp":
      destination = (current - 1 + items.length) % items.length;
      break;
    case "Home":
      destination = 0;
      break;
    case "End":
      destination = items.length - 1;
      break;
    default:
      return;
  }
  event.preventDefault();
  items[destination]?.focus();
}

